interface Visitor { }                                   // degenerate base
interface CircleVisitor extends Visitor { visitCircle(c: Circle): void; }

const isCircleVisitor = (v: Visitor): v is CircleVisitor =>
  typeof (v as CircleVisitor).visitCircle === 'function';

class Circle extends Shape {
  accept(visitor: Visitor): void {
    if (isCircleVisitor(visitor)) visitor.visitCircle(this);
  }
}
